CREATE TABLE session_probe AS SELECT current_setting('lock_timeout') AS lock_timeout, current_setting('statement_timeout') AS statement_timeout, current_setting('client_connection_check_interval') AS client_connection_check_interval, current_setting('tcp_keepalives_idle') AS tcp_keepalives_idle, current_setting('tcp_keepalives_interval') AS tcp_keepalives_interval, current_setting('tcp_keepalives_count') AS tcp_keepalives_count, current_user::text AS role_in_use, session_user::text AS login_role;
